import { formatMoney, getElements } from '../../utils/functional';
export class PushCartRenderer {
  constructor(module) {
    this.module = module;
  }

  render(state) {
    this.renderSubtotalPrice(state.total_price);
    this.renderCartCount(state.item_count);
    this.handleSubmitState(state.item_count);
  }

  renderSubtotalPrice(price) {
    this.module.subtotalEl.innerHTML = formatMoney(price);
  }

  renderCartCount(count) {
    this.module.countEls.forEach(el => el.textContent = count);
    getElements(this.module.globalSelectors.cartCount).forEach(el => el.textContent = count);
  }

  handleSubmitState(count) {
    this.module.submitEl.disabled = count < 1;
  }

}